def expand_question_library(apps, schema_editor):
    Question = apps.get_model('social', 'Question')
    now = timezone.now()
    for category, prompts in EXTRA_QUESTIONS.items():
        for text in prompts:
            Question.objects.get_or_create(
                text=text,
                category=category,
                defaults={'status': 'published', 'published_at': now},
            )


class Migration(migrations.Migration):
    dependencies = [
        ('social', '0003_question_library'),
    ]

    operations = [
        migrations.RunPython(expand_question_library, migrations.RunPython.noop),
    ]
